input.command:
# Deeper check for localhost:3003
echo "=== TCP Port Check ===" && (timeout 5 bash -c 'echo >/dev/tcp/localhost/3003' 2>&1 && echo "Port 3003 OPEN" || echo "Port 3003 CLOSED/UNREACHABLE")
echo "=== Listening Processes ===" && (ss -tlnp | grep 3003 || echo "Nothing listening on 3003")
echo "=== Curl verbose (brief) ===" && curl -v --max-time 5 "http://localhost:3003/checkConnectivity?variant=1" 2>&1 | tail -20

# Deeper check for httpstat.us
echo "=== DNS Resolution ===" && (getent hosts httpstat.us 2>&1 || host httpstat.us 2>&1 || nslookup httpstat.us 2>&1 || echo "DNS lookup failed")
echo "=== Ping ===" && (ping -c 2 -W 3 httpstat.us 2>&1 || echo "Ping failed")
echo "=== Curl verbose (brief) ===" && curl -v --max-time 10 https://httpstat.us/200 2>&1 | tail -20
